            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()

def solve(g):
    H,W=len(g),len(g[0])
    cnt=Counter(x for r in g for x in r)
    bg=cnt.most_common(1)[0][0]
    line=cnt.most_common(2)[1][0]
    sr=sorted([i for i in range(H) if sum(c==line for c in g[i])>=W*0.5])
    sc=sorted([j for j in range(W) if sum(g[i][j]==line for i in range(H))>=H*0.5])
    # marker matrix at intersections
    M=[[None]*len(sc) for _ in range(len(sr))]
    for a,i in enumerate(sr):
        for b,j in enumerate(sc):
            v=g[i][j]
            if v!=line and v not in (bg,):
                M[a][b]=v
    return sr,sc,M,line,bg

